import React, { useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { fetchMyReservations } from '../store/slices/reservationSlice';
import { useNavigate } from 'react-router-dom';
import { format, parseISO, isPast } from 'date-fns';
import { Calendar, Clock, Users, Plus } from 'lucide-react';
import LoadingSpinner from '../components/LoadingSpinner';

const STATUS_STYLES = {
  booked: 'bg-emerald-950/50 text-emerald-400 border-emerald-800',
  completed: 'bg-amber-950/50 text-amber-400 border-amber-800',
};

const BookingCard = ({ reservation }) => {
  const dateObj = parseISO(reservation?.date);

  return (
    <div className="card border transition-all duration-200 hover:border-stone-600">
      <div className="flex flex-col sm:flex-row sm:items-start sm:justify-between gap-4">
        <div className="flex-1 space-y-3">
          {/* Date & Slot */}
          <div className="flex flex-wrap gap-4">
            <div className="flex items-center gap-2 text-stone-300 text-sm">
              <Calendar size={14} className="text-amber-500" />
              {format(dateObj, 'EEEE, MMMM d, yyyy')}
            </div>

            <div className="flex items-center gap-2 text-stone-300 text-sm">
              <Clock size={14} className="text-amber-500" />
              {reservation.timeSlot?.replace('-', ':00 – ') + ':00'}
            </div>
          </div>

          {/* Guests */}
          <div className="flex items-center gap-2 text-stone-400 text-sm">
            <Users size={14} className="text-amber-500" />
            {reservation.guests} {reservation.guests === 1 ? 'guest' : 'guests'}
          </div>

          {/* Notes */}
          {reservation.notes && (
            <p className="text-stone-500 text-sm italic">
              "{reservation.notes}"
            </p>
          )}
        </div>

        {/* Status */}
        <div className="flex flex-row sm:flex-col items-center sm:items-end gap-3">
          <span
            className={`text-xs px-3 py-1 border font-mono tracking-wider uppercase ${
              STATUS_STYLES[reservation.status] || STATUS_STYLES.booked
            }`}
          >
            {reservation.status || 'booked'}
          </span>
        </div>
      </div>

      {/* Ref ID */}
      <div className="mt-4 pt-4 border-t border-stone-800">
        <p className="text-stone-600 text-xs font-mono">
          REF: {reservation._id?.slice(-8).toUpperCase()}
        </p>
      </div>
    </div>
  );
};

const MyBookings = () => {
  const dispatch = useDispatch();
  const navigate = useNavigate();


  const { user } = useSelector((s) => s.auth);

  const userId = user?.userId;

  useEffect(() => {
    if (userId) {
      dispatch(fetchMyReservations(userId));
      console.log('booking', userId);
    }
  }, [dispatch, userId]);

const upcoming = true
  const past = true

  return (
    <div className="min-h-screen bg-stone-950 pt-24 pb-16 px-4">
      <div className="max-w-3xl mx-auto page-enter">
        {/* Header */}
        <div className="flex flex-col sm:flex-row sm:items-end sm:justify-between gap-4 mb-10">
          <div>
            <p className="section-subtitle">Your Account</p>
            <h1 className="section-title">My Reservations</h1>
          </div>

          <button
            onClick={() => navigate('/reserve')}
            className="btn-gold flex items-center gap-2 self-start sm:self-auto"
          >
            <Plus size={16} />
            New Booking
          </button>
        </div>

        {loading ? (
          <div className="flex justify-center py-20">
            <LoadingSpinner size="lg" text="Loading reservations..." />
          </div>
        ) : list.length === 0 ? (
          <div className="text-center py-20">
            <div className="w-16 h-16 border border-stone-700 flex items-center justify-center mx-auto mb-6">
              <Calendar size={28} className="text-stone-600" />
            </div>

            <h3 className="font-display text-xl text-stone-400 mb-2">
              No reservations yet
            </h3>

            <p className="text-stone-600 text-sm mb-6">
              Reserve your first table at Maison Dorée
            </p>

            <button
              onClick={() => navigate('/reserve')}
              className="btn-gold"
            >
              Make a Reservation
            </button>
          </div>
        ) : (
          <div className="space-y-8">
            {/* Upcoming */}
            {upcoming.length > 0 && (
              <div>
                <h2 className="text-xs tracking-widest uppercase text-amber-500 font-mono mb-4 flex items-center gap-2">
                  <div className="w-2 h-2 bg-emerald-500 rounded-full" />
                  Upcoming ({upcoming.length})
                </h2>

                <div className="space-y-4">
                  {upcoming.map((r) => (
                    <BookingCard key={r._id} reservation={r} />
                  ))}
                </div>
              </div>
            )}

            {/* Past */}
            {past.length > 0 && (
              <div>
                <h2 className="text-xs tracking-widest uppercase text-stone-500 font-mono mb-4 flex items-center gap-2">
                  <div className="w-2 h-2 bg-stone-600 rounded-full" />
                  Past ({past.length})
                </h2>

                <div className="space-y-4">
                  {past.map((r) => (
                    <BookingCard key={r._id} reservation={r} />
                  ))}
                </div>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default MyBookings;
